from taf.gnb.oam.coam.vdu import vdu
from taf.rfrl.cbts.utilities import tl_config
from taf.rfrl.cbts.connections.ssh_connections import SSHConnExec
from taf.rfrl.cbts.utilities.generic_utils import get_unique_id_string
from taf.rfrl.cbts.utilities.global_variables import VDU_VERSION_MAPPING
from robot.api import logger
import re
import time

LOG_HEAD = LOG_END = "*" * 8


class GenericVDU(object):
    #: The object of taf.gnb.oam.coam.vdu
    vdu = vdu()

    def __init__(self):
        self.rest_connection_store = []
        self.ssh_connection_store = []

    #     self._timeout_4_rest_ope_finished = time_to_seconds(timeout_4_rest_ope_finished)
    #
    # @property
    # def timeout_4_rest_ope_finished(self):
    #     return self._timeout_4_rest_ope_finished
    #
    # @timeout_4_rest_ope_finished.setter
    # def timeout_4_rest_ope_finished(self, timeout):
    #     self._timeout_4_rest_ope_finished = time_to_seconds(timeout)

    def _connect_vdu(self, host, username, password, vdu_version, alias, timeout):
        if vdu_version:
            self.vdu.connect_to(host=host,
                                username=username,
                                password=password,
                                port='',
                                vdu_version=vdu_version,
                                secure=True,
                                connection_name=alias,
                                timeout=timeout)
        else:
            self.vdu.connect_to(host=host,
                                username=username,
                                password=password,
                                port='',
                                secure=True,
                                connection_name=alias,
                                timeout=timeout)

    def _get_vdu_version(self, gnb_index=0, vdu_index=0):
        ssh_connection = SSHConnExec()
        alias = 'vdu get version' + get_unique_id_string()
        vdu_namespace = tl_config.get_vdu_namespace(gnb_index=gnb_index, vdu_index=vdu_index)
        try:
            ssh_connection.connect_to_vdu_cloud_hosting(alias=alias, gnb_index=gnb_index, vdu_index=vdu_index)
            result = ssh_connection.execute_normal_cmd(
                "helm list -n %s | grep aic-vdu-'[0-9]'| awk '{print $9}'" % vdu_namespace, alias=alias)
            vdu_version = '.'.join(result.split('-')[-1].split('.')[:2])
        except Exception:
            return  # if get vcu_version fail will return None. And call connect_to with the default.
        finally:
            ssh_connection.disconnect_vdu_cloud_hosting(alias=alias)
        try:
            return VDU_VERSION_MAPPING[vdu_version]
        except Exception:
            logger.error(
                'The version obtained from OCP is %s, but there is no matching version of taf.gnb.oam.coam.vdu', vdu_version)

    def login_rest(self, webem_username=None, webem_password=None, vdu_version=None, gnb_index=0,
                   vdu_index=0, alias='default', timeout=30):
        """
        Rest login to vdu

        :param str webem_username: vdu webem username, default is None.
                                   If not given, oam_http_connection_details username in testline init file will be used.
        :param str webem_password: vdu webem password, default is None.
                                   If not given, oam_http_connection_details password in testline init file will be used.
        :param str vdu_version: identify the taf.gnb.oam.coam.vdu interface version, default is None.
                               If not given, the latest version will always be used.
        :param int gnb_index: gnb index in testline init file.
        :param int vdu_index: vdu index in testline init file.
        :param str alias: rest connection alias.
        :param Union[int,str] timeout: (optional) Timeout for rest connection setup, default is 30s.
        :return str: connection alias
        """

        vdu_webem_credentials = tl_config.get_vdu_webem_credentials(gnb_index=gnb_index,
                                                                    vdu_index=vdu_index)
        if not vdu_version:
            vdu_version = self._get_vdu_version(gnb_index=gnb_index, vdu_index=vdu_index)
        if webem_username:
            username = webem_username
        else:
            username = vdu_webem_credentials['username']
        if webem_password:
            password = webem_password
        else:
            password = vdu_webem_credentials['password']
        host = vdu_webem_credentials['ip']
        try:
            self._connect_vdu(host, username, password, vdu_version, alias, timeout)
        except Exception as e:
            error_msg = e.error_message
            if 'Authentication failed' in error_msg:
                response_body = e.error_message[error_msg.find('HTTP response body'):]
                response_body = response_body.replace('\n', '')
                response_body = response_body.replace('HTTP response body: ', '')
                response_body = eval(response_body)
                if response_body['status'] == 409:
                    sleep_seconds = re.findall('\\d+', response_body['detail'])[0]
                else:
                    sleep_seconds = 1
                if sleep_seconds:
                    time.sleep(int(sleep_seconds))
                self._connect_vdu(host, username, 'Nokia@123', vdu_version, alias, timeout)
            else:
                raise Exception(error_msg)

        self.rest_connection_store.append(alias)
        return alias

    def logout_rest(self, conn_alias='default'):
        """
        disconnect the vdu rest login by the given connection alias.

        :param str conn_alias: connection alias, default value is 'default'.
        :return: None
        """
        try:
            self.vdu.disconnect(vdu_connection=conn_alias)
            self.rest_connection_store.remove(conn_alias)
        except Exception:
            logger.error(
                "{} vdu Rest connection Already disconnected, no need to disconnect it once again {}".format(LOG_HEAD,
                                                                                                             LOG_END))

    def logout_all_vdu_rest(self):
        """
        disconnect all of the vdu rest connection.
        """
        for connection in self.rest_connection_store:
            try:
                self.vdu.disconnect(vdu_connection=connection)
                self.rest_connection_store.remove(connection)
            except Exception:
                continue
